#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    long long sumOfElementsWithFrequencyDivisibleByK(vector<int>& nums, int k) {
        unordered_map<int, int> freq;
        for (int x : nums) freq[x]++;
        long long total = 0;
        for (auto& [x, count] : freq) {
            if (count % k == 0) {
                total += 1LL * x * count;
            }
        }
        return total;
    }
};

import java.util.*;

class Solution {
    public long sumOfElementsWithFrequencyDivisibleByK(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : nums) freq.put(x, freq.getOrDefault(x, 0) + 1);
        long total = 0;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() % k == 0) {
                total += (long)entry.getKey() * entry.getValue();
            }
        }
        return total;
    }
}

var sumOfElementsWithFrequencyDivisibleByK = function(nums, k) {
    const freq = new Map();
    for (const x of nums) freq.set(x, (freq.get(x) || 0) + 1);
    let total = 0n;
    for (const [x, count] of freq.entries()) {
        if (count % k === 0) {
            total += BigInt(x) * BigInt(count);
        }
    }
    return Number(total);
